import smbus, time, sys

bus = smbus.SMBus(1)
addr = 0x48
p = 0x8000 | 0x4000 | 0x0200 | 0x0100

def swap(a):
    return ((a & 0xff00) >> 8) | ((a & 0x00ff) << 8)

def read(c):
    bus.write_word_data(addr, c & 0x08 | p, 0)
    time.sleep((p & 0x4000) >> 14)
    r = bus.read_word_data(addr, c & 0x08)
    return swap(r)

try:
    while 1:
        v = [read(i) for i in range(4)]
        print(v)
        time.sleep(0.05)
except KeyboardInterrupt:
    sys.exit()
finally:
    bus.close()

