import smbus
import time

# I2C address of the ADS1115 ADC
ADS1115_ADDRESS = 0x48

# Voltage divider resistor values (in ohms)
RESISTOR_TOP = 10000
RESISTOR_BOTTOM = 2000

# Initialize I2C bus
try:
    i2c_bus = smbus.SMBus(1)
except Exception as e:
    print(f"Error initializing I2C: {e}")
    exit()

# Function to read raw data from the ADS1115
def read_raw_data(channel):
    try:
        # Start single conversion on the specified channel
        i2c_bus.write_i2c_block_data(ADS1115_ADDRESS, 0x01, [0x83 + (channel << 4), 0x00])
        time.sleep(0.01)  # Wait for conversion to complete
        data = i2c_bus.read_i2c_block_data(ADS1115_ADDRESS, 0x00, 2)
        raw_adc = (data[0] << 8) | data[1]
        if raw_adc > 32767:
            raw_adc -= 65536
        return raw_adc
    except Exception as e:
        print(f"Error reading ADC data: {e}")
        return 0

# Function to convert raw ADC data to battery voltage
def convert_to_voltage(raw_adc):
    voltage = raw_adc * (3.3 / 32767) * (RESISTOR_TOP / (RESISTOR_TOP + RESISTOR_BOTTOM))
    return voltage

# Function to calculate battery percentage
def calculate_percentage(voltage):
    if voltage < 3.7:
        return 0
    elif voltage >= 4.1:
        return 100
    else:
        return int((voltage - 3.7) / (4.1 - 3.7) * 100)

try:
    last_percentage = 0
    while True:
        raw_data = read_raw_data(0)  # Read from channel 0
        battery_voltage = convert_to_voltage(raw_data)
        percentage = calculate_percentage(battery_voltage)

        if abs(percentage - last_percentage) > 1:
            print(f"Battery Voltage: {battery_voltage:.2f}V, Charge: {percentage}%")
            last_percentage = percentage

        time.sleep(1)

except KeyboardInterrupt:
    print("Exiting program")
finally:
    i2c_bus.close()

