import RPi.GPIO as GPIO
import time
import logging
import json
import signal
import sys
import os

# Constants and configuration
CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sensor1": {"offset": 0.0, "max_distance": 200.0},
    "sensor2": {"offset": 0.0, "max_distance": 200.0},
    "sensor3": {"offset": 0.0, "max_distance": 200.0},
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log"
}

# GPIO pin assignments
TRIG_PINS = [17, 22, 24]
ECHO_PINS = [18, 23, 25]

# Global variables
sensor_status = {"sensor1": "OK", "sensor2": "OK", "sensor3": "OK"}
last_alert_time = {}
running = True

# Custom exception classes
class SensorTimeoutError(Exception):
    pass

class ConfigurationError(Exception):
    pass

# Configuration management functions
def load_config(config_file):
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
        return config
    except FileNotFoundError:
        logging.warning(f"Configuration file not found. Using default configuration.")
        return DEFAULT_CONFIG
    except json.JSONDecodeError:
        logging.error(f"Error decoding JSON from {config_file}. Using default configuration.")
        return DEFAULT_CONFIG
    except Exception as e:
        logging.error(f"Unexpected error loading config: {e}. Using default configuration.")
        return DEFAULT_CONFIG

def validate_config(config):
    for sensor, data in config.items():
        if not all(key in data for key in ["offset", "max_distance"]):
            raise ConfigurationError(f"Missing keys in sensor configuration for {sensor}")
        if not isinstance(data["offset"], (int, float)) or not isinstance(data["max_distance"], (int, float)):
            raise ConfigurationError(f"Invalid type for offset or max_distance in {sensor}")
        if not isinstance(config.get("alert_threshold_low", 10.0), (int, float)) or not isinstance(config.get("alert_threshold_high", 180.0), (int, float)):
            raise ConfigurationError("Invalid type for alert_threshold_low or alert_threshold_high")
        if not isinstance(config.get("alert_repeat_delay", 60), int):
            raise ConfigurationError("Invalid type for alert_repeat_delay")
    return config

# Modular subsystem functions
def read_distance(trigger_pin, echo_pin):
    try:
        GPIO.output(trigger_pin, True)
        time.sleep(0.00001)
        GPIO.output(trigger_pin, False)

        pulse_start = time.time()
        pulse_end = time.time()

        timeout_start = time.time()
        while GPIO.input(echo_pin) == 0:
            pulse_start = time.time()
            if time.time() - timeout_start > 0.05:  # 50ms timeout
                raise SensorTimeoutError("Echo signal timeout (low)")
            time.sleep(0.00001)

        timeout_start = time.time()
        while GPIO.input(echo_pin) == 1:
            pulse_end = time.time()
            if time.time() - timeout_start > 0.05:  # 50ms timeout
                raise SensorTimeoutError("Echo signal timeout (high)")
            time.sleep(0.00001)

        pulse_duration = pulse_end - pulse_start
        distance = (pulse_duration * 34300) / 2  # Speed of sound in cm/s
        return distance
    except SensorTimeoutError as e:
        logging.error(f"Sensor timeout on trigger {trigger_pin}: {e}")
        return None
    except Exception as e:
        logging.error(f"Error reading distance from sensor on trigger {trigger_pin}: {e}")
        return None

def calculate_water_level(distance, offset, max_distance):
    if distance is None:
        return None
    distance = max(0, min(max_distance, distance - offset))
    return distance

def check_thresholds(water_level, alert_threshold_low, alert_threshold_high, alert_repeat_delay):
    global last_alert_time
    if water_level is None:
        return

    if water_level < alert_threshold_low and (sensor1_level is None or sensor2_level is None or sensor3_level is None):
        logging.warning(f"Low water level: {water_level:.2f} cm")
        if "sensor1" not in last_alert_time or time.time() - last_alert_time["sensor1"] > alert_repeat_delay:
            logging.warning(f"Low water level alert triggered for sensor 1: {water_level:.2f} cm")
            last_alert_time["sensor1"] = time.time()
    elif water_level > alert_threshold_high and (sensor1_level is None or sensor2_level is None or sensor3_level is None):
        logging.warning(f"High water level: {water_level:.2f} cm")
        if "sensor2" not in last_alert_time or time.time() - last_alert_time["sensor2"] > alert_repeat_delay:
            logging.warning(f"High water level alert triggered for sensor 2: {water_level:.2f} cm")
            last_alert_time["sensor2"] = time.time()

# Resource management functions
def setup_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        for pin in TRIG_PINS + ECHO_PINS:
            GPIO.setup(pin, GPIO.OUT if pin in TRIG_PINS else GPIO.IN)
        GPIO.output(TRIG_PINS, False)
        time.sleep(2)
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        raise

def cleanup_gpio():
    GPIO.cleanup()

# Signal handlers
def signal_handler(sig, frame):
    global running
    logging.info("Shutting down gracefully...")
    running = False

# Logging configuration and utilities
def setup_logging(log_file):
    logging.basicConfig(filename=log_file, level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')

# Main program orchestration
def main():
    global sensor_status, last_alert_time, running
    try:
        setup_logging(load_config(CONFIG_FILE).get("log_file", DEFAULT_CONFIG["log_file"]))
        config = load_config(CONFIG_FILE)
        config = validate_config(config)

        alert_threshold_low = config.get("alert_threshold_low", DEFAULT_CONFIG["alert_threshold_low"])
        alert_threshold_high = config.get("alert_threshold_high", DEFAULT_CONFIG["alert_threshold_high"])
        alert_repeat_delay = config.get("alert_repeat_delay", DEFAULT_CONFIG["alert_repeat_delay"])

