import cv2
import time
import sys
import hardware
import config

# Global variables
face_cascade = None
camera = None
box = None

def initialize():
    """Initializes hardware and software components."""
    global face_cascade, camera, box
    try:
        box = hardware.Box()
        box.lock()  # Start locked
        camera = config.get_camera()
        camera.start_preview()
        camera.set_pixel_format(config.PIXEL_FORMAT)
        camera.resolution = config.get_resolution()
        face_cascade = cv2.CascadeClassifier(config.TRAINING_FILE)
        if face_cascade.empty():
            raise IOError("Unable to load face cascade classifier.")
    except Exception as e:
        print(f"Initialization error: {e}")
        cleanup()
        sys.exit(1)

def process_frame():
    """Captures a frame, detects faces, and attempts recognition."""
    global camera
    try:
        image = camera.capture()
        gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        faces = face_cascade.detectMultiScale(gray, config.FACE_SCALE_FACTOR, config.FACE_MIN_NEIGHBORS)
        if len(faces) > 0:
            (x, y, w, h) = faces[0]
            cropped_face = gray[y:y+h, x:x+w]
            resized_face = cv2.resize(cropped_face, (10, 10), interpolation=cv2.INTER_LANCZOS4)
            label, confidence = config.recognize(resized_face)
            print(f"Label: {label}, Confidence: {confidence}")
            if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                box.unlock()
            elif box.is_unlocked:
                box.lock()
        else:
            if box.is_unlocked:
                box.lock()
    except Exception as e:
        print(f"Processing error: {e}")

def cleanup():
    """Releases resources and resets hardware."""
    global camera, box
    try:
        if camera:
            camera.stop_preview()
            camera.close()
        if box:
            box.lock()  # Ensure box is locked on exit
    except Exception as e:
        print(f"Cleanup error: {e}")

def main_loop():
    """Main event loop for the face recognition door controller."""
    global camera
    try:
        while True:
            if box.is_button_up() and camera.exposure_mode == 'off':
                process_frame()
            time.sleep(0.1)  # Reduced delay for responsiveness
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        cleanup()

if __name__ == "__main__":
    initialize()
    main_loop()

