import RPi.GPIO as GPIO
import picamera
import time
import os
import datetime

# Define GPIO pin for the LED indicator
LED_PIN = 17

# Define the directory to save captured images
IMAGE_DIR = "static/images"

def initialize_gpio():
    """Initializes the GPIO pin for the LED."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LED_PIN, GPIO.OUT)

def initialize_camera():
    """Initializes the Raspberry Pi camera."""
    try:
        camera = picamera.PiCamera()
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def create_image_directory():
    """Creates the image directory if it doesn't exist."""
    try:
        if not os.path.exists(IMAGE_DIR):
            os.makedirs(IMAGE_DIR)
    except OSError as e:
        print(f"Error creating directory: {e}")
        return False
    return True

def blink_led(pin, num_blinks, on_time, off_time):
    """Blinks the LED a specified number of times."""
    for _ in range(num_blinks):
        GPIO.output(pin, GPIO.HIGH)
        time.sleep(on_time)
        GPIO.output(pin, GPIO.LOW)
        time.sleep(off_time)

def countdown(n):
    """Displays a countdown on the camera preview."""
    for i in range(n, 0, -1):
        print(i)
        time.sleep(1)

def capture_image(camera, directory):
    """Captures an image and saves it to the specified directory."""
    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    image_path = os.path.join(directory, f"image_{timestamp}.jpg")
    try:
        camera.capture(image_path)
        print(f"Image saved to {image_path}")
        return True
    except Exception as e:
        print(f"Error capturing image: {e}")
        return False

def main():
    """Main function to run the image capture with LED indicator."""
    try:
        initialize_gpio()
        camera = initialize_camera()
        if camera is None:
            blink_led(LED_PIN, 5, 0.2, 0.2)
            return

        if not create_image_directory():
            blink_led(LED_PIN, 5, 0.2, 0.2)
            return

        blink_led(LED_PIN, 5, 0.2, 0.2)  # Initial blink sequence
        countdown(2)
        GPIO.output(LED_PIN, GPIO.HIGH)  # LED on
        if capture_image(camera, IMAGE_DIR):
            GPIO.output(LED_PIN, GPIO.LOW)  # LED off
        else:
            blink_led(LED_PIN, 5, 0.2, 0.2) # Error blink

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        blink_led(LED_PIN, 5, 0.2, 0.2) # Error blink
    finally:
        if 'camera' in locals() and camera is not None:
            camera.close()
        GPIO.cleanup()
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

