import serial
import time
import sys

# Define Bluetooth serial port and baud rate
BLUETOOTH_PORT = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400

def open_bluetooth_port(port, baudrate):
    """Opens the Bluetooth serial port."""
    try:
        bluetooth = serial.Serial(port, baudrate, timeout=1)
        return bluetooth
    except serial.SerialException as e:
        print(f"Error opening Bluetooth port: {e}")
        return None

def send_command(bluetooth, command):
    """Sends a command over the Bluetooth connection."""
    try:
        data = f"X{command}\n"
        bluetooth.write(data.encode("utf-8"))
        print(f"Sent command: {data.strip()}")
        return True
    except serial.SerialException as e:
        print(f"Error sending command: {e}")
        return False

def main():
    """Main function to handle user input and send commands."""
    bluetooth = open_bluetooth_port(BLUETOOTH_PORT, BLUETOOTH_BAUD_RATE)

    if bluetooth is None:
        print("Failed to open Bluetooth port. Exiting.")
        return

    try:
        while True:
            user_input = input("Enter command (or 'q' to quit): ")
            if user_input.lower() == "q":
                break
            if send_command(bluetooth, user_input):
                print(f"Bytes sent: {bluetooth.write_count}")
            else:
                print("Command not sent.")
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        if bluetooth and bluetooth.is_open:
            bluetooth.close()
            print("Bluetooth port closed.")

if __name__ == "__main__":
    main()

