    """Creates a directory if it doesn't exist."""
    try:
        os.makedirs(directory_name, exist_ok=True)
        print(f"Directory '{directory_name}' created or already exists.")
    except OSError as e:
        print(f"Error creating directory '{directory_name}': {e}")
        return False
    return True

def initialize_camera(camera_index=0, max_attempts=3):
    """Initializes the camera with error handling."""
    for attempt in range(max_attempts):
        try:
            capture = cv2.VideoCapture(camera_index)
            if capture.isOpened():
                return capture
            else:
                print(f"Attempt {attempt + 1}: Could not open camera {camera_index}.")
        except Exception as e:
            print(f"Attempt {attempt + 1}: Error initializing camera: {e}")
        time.sleep(1)
    print("Failed to initialize camera after multiple attempts.")
    return None

def capture_frame(capture):
    """Captures a single frame from the camera."""
    ret, frame = capture.read()
    if not ret:
        print("Failed to capture frame.")
        return None
    return frame

def detect_faces(frame, face_cascade):
    """Detects faces in a frame using the provided cascade classifier."""
    gray_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    return face_cascade.detectMultiScale(gray_frame, 1.3, 5)

def draw_rectangle(frame, faces):
    """Draws rectangles around detected faces in the frame."""
    for (x, y, w, h) in faces:
        cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

def save_image(frame, image_path):
    """Saves the given frame to the specified image path."""
    try:
        cv2.imwrite(image_path, frame)
        print(f"Image saved to: {image_path}")
    except Exception as e:
