    except Exception as e:
        print(f"Error loading face cascade classifier: {e}")
        return

    capture = initialize_camera()
    if capture is None:
        return

    image_count = 1
    max_images = 5

    try:
        while image_count <= max_images:
            frame = capture_frame(capture)
            if frame is None:
                break

            faces = detect_faces(frame, face_cascade)

            if len(faces) > 0:
                draw_rectangle(frame, faces)
                image_path = os.path.join(directory_name, f"{name}{image_count}.jpg")
                save_image(frame, image_path)
                image_count += 1
                print(f"Captured image {image_count - 1}/{max_images}")
                time.sleep(0.5)  # Add a small delay to avoid overwhelming the system

            cv2.imshow('Face Capture', frame)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    finally:
        capture.release()
        cv2.destroyAllWindows()
        print("Exiting program.")

