FRAME_HEIGHT = 480

def initialize_camera():
    """Initializes the camera and returns the capture object."""
    try:
        capture = cv2.VideoCapture(0)
        capture.set(cv2.CAP_PROP_FRAME_WIDTH, FRAME_WIDTH)
        capture.set(cv2.CAP_PROP_FRAME_HEIGHT, FRAME_HEIGHT)
        return capture
    except Exception as e:
        print(f"Error initializing camera: {e}")
        sys.exit(1)

def load_face_cascade(cascade_file):
    """Loads the face cascade classifier."""
    try:
        face_cascade = cv2.CascadeClassifier(cascade_file)
        if face_cascade.empty():
            raise IOError('Unable to load the face cascade classifier XML file')
        return face_cascade
    except Exception as e:
        print(f"Error loading face cascade: {e}")
        sys.exit(1)

def detect_faces(frame, face_cascade):
    """Detects faces in a frame and returns the detected faces."""
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    return face_cascade.detectMultiScale(gray, scaleFactor=1.3, minNeighbors=5)

def draw_rectangles(frame, faces):
    """Draws rectangles around the detected faces in the frame."""
    for (x, y, w, h) in faces:
        cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 255, 0), 2)

