import serial
import time
import csv
import sys

# Configuration for the UART port
uart_port = '/dev/ttyACM0'
baud_rate = 115200
timeout_seconds = 1

# CSV file for logging temperature data
log_file_name = 'temperature_log.csv'

def initialize_uart(port, baud, timeout):
    """Initializes the UART serial port."""
    try:
        uart = serial.Serial(port, baud, timeout=timeout)
        return uart
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
        return None

def read_temperature(uart):
    """Reads temperature data from the UART port."""
    try:
        line = uart.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Invalid data received from sensor.", file=sys.stderr)
        return None

def log_temperature(log_file, celsius_temp, fahrenheit_temp):
    """Logs the temperature data to a CSV file."""
    try:
        with open(log_file, 'a', newline='') as csvfile:
            csv_writer = csv.writer(csvfile)
            if csvfile.tell() == 0:  # Write header only if the file is empty
                csv_writer.writerow(['Timestamp', 'Celsius', 'Fahrenheit'])
            csv_writer.writerow([time.strftime('%Y-%m-%d %H:%M:%S'), celsius_temp, fahrenheit_temp])
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    """Main function to read temperature and log data."""
    uart_connection = initialize_uart(uart_port, baud_rate, timeout_seconds)

    if uart_connection is None:
        sys.exit(1)

    try:
        # Check if the log file exists and write the header if it doesn't
        file_exists = True
        try:
            with open(log_file_name, 'r') as f:
                pass
        except FileNotFoundError:
            file_exists = False

        while True:
            temperature_c = read_temperature(uart_connection)
            if temperature_c is not None:
                temperature_f = (temperature_c * 9/5) + 32
                log_temperature(log_file_name, temperature_c, temperature_f)
                print(f"Temperature: {temperature_c:.2f}C / {temperature_f:.2f}F")
            time.sleep(1)  # Avoid busy-waiting

    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        if uart_connection:
            uart_connection.close()
        sys.exit(0)

if __name__ == "__main__":
    main()

