import time
import board
import busio
import adafruit_bmp280

# Configuration constants
BASELINE_READ_DELAY = 1  # seconds
BASELINE_COLLECTION_TIME = 10  # seconds
ALTITUDE_READ_DELAY = 1  # seconds

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_bmp280(i2c_bus):
    """Initializes the BMP280 sensor."""
    try:
        return adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus)
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        return None

def collect_baseline_pressure(sensor, duration):
    """Collects baseline pressure readings and calculates the average."""
    print("Collecting baseline pressure...")
    pressure_readings = []
    start_time = time.time()
    while time.time() - start_time < duration:
        try:
            pressure = sensor.pressure
            pressure_readings.append(pressure)
            time.sleep(BASELINE_READ_DELAY)
        except OSError as e:
            print(f"Error reading pressure during baseline collection: {e}")
            continue
    if not pressure_readings:
        print("No pressure readings collected. Exiting.")
        return None
    # Exclude the first two readings to avoid early sensor instability
    baseline_pressure = sum(pressure_readings[2:]) / len(pressure_readings[2:])
    print(f"Baseline pressure: {baseline_pressure:.2f} hPa")
    return baseline_pressure

def read_altitude(sensor, baseline_pressure):
    """Reads and prints the relative altitude."""
    try:
        altitude = sensor.altitude
        print(f"Relative altitude: {altitude:.2f} meters")
    except OSError as e:
        print(f"Error reading altitude: {e}")

def main():
    """Main function to run the altitude monitoring."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    bmp280_sensor = initialize_bmp280(i2c_bus)
    if bmp280_sensor is None:
        return

    baseline_pressure = collect_baseline_pressure(bmp280_sensor, BASELINE_COLLECTION_TIME)
    if baseline_pressure is None:
        return

    try:
        while True:
            read_altitude(bmp280_sensor, baseline_pressure)
            time.sleep(ALTITUDE_READ_DELAY)
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

