# Script to monitor altitude using a BMP280 sensor on a Raspberry Pi
# Target: Raspberry Pi 3, 4, or 5
# Context: STEM Education

import time
import smbus2
import adafruit_bmp280

# I2C configuration
I2C_BUS = 1
SEA_LEVEL_PRESSURE = 1013.25  # Standard sea level pressure in hPa

def initialize_sensor():
    """Initializes the BMP280 sensor."""
    try:
        i2c_bus = smbus2.SMBus(I2C_BUS)
        bmp280 = adafruit_bmp280.BMP280_I2C(i2c_bus)
        return bmp280
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        return None

def read_sensor_data(sensor):
    """Reads pressure and altitude from the sensor."""
    try:
        pressure = sensor.pressure
        altitude = sensor.altitude
        return pressure, altitude
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def log_data(pressure, altitude):
    """Logs the pressure and altitude data to a file."""
    try:
        with open("altitude_log.txt", "a") as log_file:
            timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
            log_file.write(f"{timestamp} – Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read and log sensor data."""
    sensor = initialize_sensor()
    if sensor is None:
        print("Failed to initialize sensor. Exiting.")
        return 1

    try:
        while True:
            pressure, altitude = read_sensor_data(sensor)
            if pressure is not None and altitude is not None:
                print(f"Pressure: {pressure:.2f} hPa, Altitude: {altitude:.2f} meters")
                log_data(pressure, altitude)
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Exiting program.")

if __name__ == "__main__":
    exit_code = main()
    if exit_code is not None:
        exit(exit_code)

