import smbus2
import sqlite3
import time
import datetime
import logging
import threading
from flask import Flask, render_template
import RPi.GPIO as GPIO

# Configuration
I2C_BUS = 1
BME280_ADDRESS = 0x76
VIBRATION_MOTOR_PIN = 17
DATABASE_PATH = '/home/pi/wearable_data.db'
LOG_FILE = '/home/pi/wearable_sensor.log'
WEB_PORT = 5000
SAMPLE_INTERVAL = 5  # seconds
DEBOUNCE_DELAY = 5  # seconds
VIBRATION_DURATION = 1  # seconds

# Initialize logging
logging.basicConfig(filename=LOG_FILE, level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Initialize Flask app
app = Flask(__name__)

# Initialize GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(VIBRATION_MOTOR_PIN, GPIO.OUT)
GPIO.output(VIBRATION_MOTOR_PIN, GPIO.LOW)  # Ensure motor is off initially

# Global variables
last_vibration_time = 0
data_lock = threading.Lock()
data_queue = []

# BME280 Registers
BME280_REGISTER_TEMP_DATA = 0xFA
BME280_REGISTER_PRESSURE_DATA = 0xF7
BME280_REGISTER_CONTROL_MEAS = 0xF4
BME280_REGISTER_CONFIG = 0xF5
BME280_REGISTER_CONTROL_HUM = 0xF2

# BME280 Calibration Data Registers
BME280_REGISTER_DIG_T1 = 0x88
BME280_REGISTER_DIG_T2 = 0x8A
BME280_REGISTER_DIG_T3 = 0x8C
BME280_REGISTER_DIG_P1 = 0x8E
BME280_REGISTER_DIG_P2 = 0x90
BME280_REGISTER_DIG_P3 = 0x92
BME280_REGISTER_DIG_P4 = 0x94
BME280_REGISTER_DIG_P5 = 0x96
BME280_REGISTER_DIG_P6 = 0x98
BME280_REGISTER_DIG_P7 = 0x9A
BME280_REGISTER_DIG_P8 = 0x9C
BME280_REGISTER_DIG_P9 = 0x9E
BME280_REGISTER_DIG_H1 = 0xA1
BME280_REGISTER_DIG_H2 = 0xE1
BME280_REGISTER_DIG_H3 = 0xE3
BME280_REGISTER_DIG_H4 = 0xE4
BME280_REGISTER_DIG_H5 = 0xE5
BME280_REGISTER_DIG_H6 = 0xE6

# Calibration data
dig_T1 = 0
dig_T2 = 0
dig_T3 = 0
dig_P1 = 0
dig_P2 = 0
dig_P3 = 0
dig_P4 = 0
dig_P5 = 0
dig_P6 = 0
dig_P7 = 0
dig_P8 = 0
dig_P9 = 0
dig_H1 = 0
dig_H2 = 0
dig_H3 = 0
dig_H4 = 0
dig_H5 = 0
dig_H6 = 0

# Function to read calibration data
def read_calibration_data(bus):
    global dig_T1, dig_T2, dig_T3, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9, dig_H1, dig_H2, dig_H3, dig_H4, dig_H5, dig_H6
    try:
        dig_T1 = bus.read_word_data(BME280_ADDRESS, BME280_REGISTER_DIG_T1)
        dig_T2 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_T2, 2))
        dig_T3 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_T3, 2))

        dig_P1 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_P1, 2))
        dig_P2 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_P2, 2))
        dig_P3 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_P3, 2))
        dig_P4 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_P4, 2))
        dig_P5 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_P5, 2))
        dig_P6 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_P6, 2))
        dig_P7 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_P7, 2))
        dig_P8 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_P8, 2))
        dig_P9 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_P9, 2))

        dig_H1 = bus.read_byte_data(BME280_ADDRESS, BME280_REGISTER_DIG_H1)
        dig_H2 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_H2, 2))
        dig_H3 = bus.read_byte_data(BME280_ADDRESS, BME280_REGISTER_DIG_H3)
        dig_H4 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_H4, 2))
        dig_H5 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_H5, 2))
        dig_H6 = twos_complement(bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_DIG_H6, 2))

        logging.info("Calibration data read successfully.")
    except Exception as e:
        logging.error(f"Error reading calibration data: {e}")

# Function to convert two's complement to signed integer
def twos_complement(data):
    val = data[0] | (data[1] << 8)
    if val >= 0x8000:
        return -((0xFFFF - val) + 1)
    else:
        return val

# Function to read raw data from BME280
def read_raw_data(bus):
    try:
        data = bus.read_i2c_block_data(BME280_ADDRESS, BME280_REGISTER_TEMP_DATA, 8)
        pressure_raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
        temperature_raw = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4)
        humidity_raw = (data[6] << 8) | data[7]
        return temperature_raw, pressure_raw, humidity_raw
    except Exception as e:
        logging.error(f"Error reading raw data: {e}")
        return None, None, None

# Function to compensate temperature
def compensate_temperature(adc_T):
    global dig_T1, dig_T2, dig_T3
    var1 = (adc_T / 16384.0 - dig_T1 / 1024.0) * dig_T2
    var2 = ((adc_T / 131072.0 - dig_T1 / 8192.0) * (adc_T / 131072.0 - dig_T1 / 8192.0)) * dig_T3
    t_fine = var1 + var2
    temperature = t_fine / 5120.0
    return temperature, t_fine

# Function to compensate pressure
def compensate_pressure(adc_P, t_fine):
    global dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9
    var1 = (t_fine / 2.0) - 64000.0
    var2 = var1 * var1 * dig_P6 / 32768.0
    var2 = var2 + var1 * dig_P5 * 2.0
    var2 = (var2 / 4.0) + (dig_P4 * 65536.0)
    var1 = (dig_P3 * var1 * var1 / 524288.0 + dig_P2 * var1) / 524288.0
    var1 = (1.0 + var1 / 32768.0) * dig_P1
    if var1 == 0:
        return 0  # Avoid exception caused by division by zero
    pressure = 1048576.0 - adc_P
    pressure = (pressure - (var2 / 4096.0)) * 6250.0 / var1
    var1 = dig_P9 * pressure * pressure / 2147483648.0
    var2 = pressure * dig_P8 / 32768.0
    pressure = pressure + (var1 + var2 + dig_P7) / 16.0
    return pressure

# Function to compensate humidity
def compensate_humidity(adc_H, t_fine):
    global dig_H1, dig_H2, dig_H3, dig_H4, dig_H5, dig_H6
    var_h = t_fine - 76800.0
    if var_h != 0:
        var_h = (adc_H - (dig_H4 * 64.0 + dig_H5 / 16384.0 * var_h)) * (dig_H2 / 65536.0 * (1.0 + dig_H6 / 67108864.0 * var_h * (1.0 + dig_H3 / 67108864.0 * var_h)))
    else:
        var_h = 0
    if var_h < 0:
        var_h = 0
    if var_h > 100.0:
        var_h = 100.0
    return var_h

# Function to validate sensor data
def validate_data(temperature, humidity, pressure):
    if not (-40 <= temperature <= 85 and 0 <= humidity <= 100 and 30000 <= pressure <= 110000):
        logging.warning(f"Invalid sensor data: temp={temperature}, humidity={humidity}, pressure={pressure}")
        return False
    return True

# Function to store data in the database
def store_data(timestamp, temperature, humidity, pressure):
    try:
        with sqlite3.connect(DATABASE_PATH) as conn:
            cursor = conn.cursor()
            cursor.execute('''
                CREATE TABLE IF NOT EXISTS sensor_data (
                    timestamp TEXT PRIMARY KEY,
                    temperature REAL,
                    humidity REAL,
                    pressure REAL
                )
            ''')
            cursor.execute('''
                INSERT INTO sensor_data (timestamp, temperature, humidity, pressure)
                VALUES (?, ?, ?, ?)
            ''', (timestamp, temperature, humidity, pressure))
            conn.commit()
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")

# Function to get the latest sensor data
def get_latest_data():
    try:
        with sqlite3.connect(DATABASE_PATH) as conn:
            cursor = conn.cursor()
            cursor.execute("SELECT timestamp, temperature, humidity, pressure FROM sensor_data ORDER BY timestamp DESC LIMIT 1")
            row = cursor.fetchone()
            if row:
                return {'timestamp': row[0], 'temperature': row[1], 'humidity': row[2], 'pressure': row[3]}
            else:
                return None
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")
        return None

# Function to trigger vibration motor
def trigger_vibration():
    global last_vibration_time
    current_time = time.time()
    if current_time - last_vibration_time > DEBOUNCE_DELAY:
        logging.info("Triggering vibration motor.")
        GPIO.output(VIBRATION_MOTOR_PIN, GPIO.HIGH)
        time.sleep(VIBRATION_DURATION)
        GPIO.output(VIBRATION_MOTOR_PIN, GPIO.LOW)
        last_vibration_time = current_time

# Data acquisition thread
def data_acquisition_thread():
    global data_queue
    bus = smbus2.SMBus(I2C_BUS)
    read_calibration_data(bus)
    bus.write_byte_data(BME280_ADDRESS, BME280_REGISTER_CONTROL_HUM, 0x01) # Humidity oversampling x1
    bus.write_byte_data(BME280_ADDRESS, BME280_REGISTER_CONTROL_MEAS, 0x25) # Forced mode, temp x1, pressure x1, humidity x1
    bus.write_byte_data(BME280_ADDRESS, BME280_REGISTER_CONFIG, 0x00) # Normal mode, t_sb = 0.5ms, filter = off, spi3w_en = off

    while True:
        try:
            temperature_raw, pressure_raw, humidity_raw = read_raw_data(bus)
            if temperature_raw is not None and pressure_raw is not None and humidity_raw is not None:
                temperature, t_fine = compensate_temperature(temperature_raw)
                pressure = compensate_pressure(pressure_raw, t_fine)
                humidity = compensate_humidity(humidity_raw, t_fine)

                if validate_data(temperature, humidity, pressure):
                    timestamp = datetime.datetime.utcnow().isoformat() + 'Z'
                    with data_lock:
                        data_queue.append((timestamp, temperature, humidity, pressure))
                    trigger_vibration() # Trigger vibration based on sensor data
                else:
                    logging.warning("Invalid data, skipping storage.")
            else:
                logging.warning("Failed to read sensor data.")
        except Exception as e:
            logging.error(f"Error in data acquisition thread: {e}")
        time.sleep(SAMPLE_INTERVAL)

# Flask route to display sensor data
