import serial
import time
import logging

# Configure logging for the environmental monitoring system
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define serial port and baud rate for the sensor
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600

# Define temperature and humidity thresholds for alerts
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

def initialize_serial(port, baud):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baud, timeout=1)
        logging.info(f"Serial connection established on {port} at {baud} baud.")
        return ser
    except serial.SerialException as e:
        logging.error(f"Failed to initialize serial port: {e}")
        return None

def read_sensor_data(serial_connection):
    """Reads temperature and humidity data from the serial port."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            temperature, humidity = map(float, line.split(','))
            logging.info(f"Temperature: {temperature}°C, Humidity: {humidity}%")
            return temperature, humidity
        else:
            logging.warning("No data received from sensor.")
            return None, None
    except ValueError as e:
        logging.error(f"Error parsing sensor data: {e}")
        return None, None
    except Exception as e:
        logging.error(f"Error reading sensor data: {e}")
        return None, None

def check_thresholds(temperature, humidity):
    """Checks if temperature and humidity exceed defined thresholds."""
    if temperature > TEMPERATURE_THRESHOLD:
        logging.warning(f"Temperature exceeds threshold: {temperature}°C > {TEMPERATURE_THRESHOLD}°C")
    if humidity > HUMIDITY_THRESHOLD:
        logging.warning(f"Humidity exceeds threshold: {humidity}% > {HUMIDITY_THRESHOLD}%")

def main():
    """Main function to read sensor data and check thresholds."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE)

    if serial_connection is None:
        logging.error("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(serial_connection)

            if temperature is not None and humidity is not None:
                check_thresholds(temperature, humidity)

            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            logging.info("Serial connection closed.")

if __name__ == "__main__":
    main()

