import time
import board
import busio
import digitalio
import adafruit_mcp23017

# Configuration constants
I2C_BUS = board.I2C
DEVICE_ADDRESS = 0x20
LED_PIN = 0
SWITCH_PIN = 7
LED_PIN_REGISTER = 'A'
SWITCH_PIN_REGISTER = 'B'
POLL_INTERVAL = 0.1
LED_ON_MESSAGE = "Led ON"
LED_OFF_MESSAGE = "Led OFF"


def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None


def initialize_gpio_expander(i2c_bus, device_address):
    """Initialize the MCP23017 GPIO expander."""
    try:
        return adafruit_mcp23017.MCP23017(i2c_bus, device_address)
    except Exception as e:
        print(f"Error initializing MCP23017: {e}")
        return None


def setup_gpio(gpio_expander):
    """Configure GPIO pins for LED and switch."""
    try:
        led = digitalio.DigitalInOut(gpio_expander.get_pin(f'{LED_PIN_REGISTER}{LED_PIN}'))
        led.direction = digitalio.Direction.OUTPUT

        switch = digitalio.DigitalInOut(gpio_expander.get_pin(f'{SWITCH_PIN_REGISTER}{SWITCH_PIN}'))
        switch.direction = digitalio.Direction.INPUT
        switch.pull = digitalio.Pull.UP  # Enable pull-up resistor

        return led, switch
    except Exception as e:
        print(f"Error setting up GPIO pins: {e}")
        return None, None


def main():
    """Main function to control the LED based on switch state."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    gpio_expander = initialize_gpio_expander(i2c_bus, DEVICE_ADDRESS)
    if gpio_expander is None:
        return

    led, switch = setup_gpio(gpio_expander)
    if led is None or switch is None:
        return

    led_state = None

    try:
        while True:
            try:
                switch_state = switch.value
                if switch_state != led_state:
                    if switch_state:
                        led.value = False
                        print(LED_OFF_MESSAGE)
                    else:
                        led.value = True
                        print(LED_ON_MESSAGE)
                    led_state = switch_state
                time.sleep(POLL_INTERVAL)
            except Exception as e:
                print(f"Error during main loop: {e}")
                time.sleep(POLL_INTERVAL)  # Prevent excessive error printing

    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        # Ensure LED is off on exit
        led.value = False
        print("Led OFF")


if __name__ == "__main__":
    main()

