import DOGProtocol as DOG
import RPi.GPIO as GPIO
import time
import signal
import sys
import os

# Constants
DEFAULT_LOG_FILE = "data.log"
POLL_INTERVAL = 0.1  # seconds

# Global variables
data_file_path = DEFAULT_LOG_FILE
receive_thread = None
running = True

# Help messages
help_messages = {
    "help": "Shows this help message. Usage: 'help' or 'help <command>'",
    "start": "Starts listening and logging data from the DOG device. Usage: 'start <filename>'",
    "stop": "Stops listening and logging data. Usage: 'stop'",
    "display": "Displays the contents of the log file. Usage: 'display'",
    "send": "Sends data using the DOG protocol. Usage: 'send <data>'",
    "write": "Writes data directly to the log file. Usage: 'write <data>'",
    "exit": "Exits the program. Usage: 'exit'"
}


def initialize_gpio():
    """Initializes GPIO settings."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)


def signal_handler(sig, frame):
    """Handles signals for clean exit."""
    global running
    running = False
    print("\nExiting gracefully...")


def start_listening(filename):
    """Starts listening for data and logs it to a file."""
    global receive_thread, running

    if receive_thread and receive_thread.is_alive():
        print("Already listening. Stop the current session first.")
        return

    try:
        with open(filename, "a") as f:
            pass  # Check if file exists and is writable
    except Exception as e:
        print(f"Error opening file: {e}")
        return

    try:
        receive_thread = DOG.receiveData(data_file_path)
        receive_thread.deamon = True  # Allow main thread to exit even if this is running
        receive_thread.start()
        print(f"Listening and logging data to {filename}")
    except Exception as e:
        print(f"Error starting receive thread: {e}")
        running = False  # Ensure loop exits


def stop_listening():
    """Stops listening for data."""
    global receive_thread, running
    running = False
    if receive_thread and receive_thread.is_alive():
        receive_thread.join(timeout=1)  # Wait for thread to finish, but not indefinitely
        print("Stopped listening.")
    else:
        print("Not currently listening.")


def display_log():
    """Displays the contents of the log file."""
    try:
        with open(data_file_path, "r") as f:
            print(f.read())
    except FileNotFoundError:
        print("Log file not found.")
    except Exception as e:
        print(f"Error reading log file: {e}")


def send_data(data):
    """Sends data using the DOG protocol."""
    try:
        DOG.send(data, 0)  # Assuming 0 is a valid parameter
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")


def write_to_log(data):
    """Writes data directly to the log file."""
    try:
        with open(data_file_path, "a") as f:
            f.write(data + "\n")
        print(f"Wrote to log: {data}")
    except Exception as e:
        print(f"Error writing to log file: {e}")


def print_help(command=None):
    """Prints help information for a command."""
    if command:
        message = help_messages.get(command)
        if message:
            print(message)
        else:
            print(f"No help found for command '{command}'")
    else:
        for cmd, msg in help_messages.items():
            print(f"{cmd}: {msg}")


def process_command(command):
    """Processes user commands."""
    parts = command.split()
    if not parts:
        return

    cmd = parts[0].lower()

    if cmd == "help":
        if len(parts) > 1:
            print_help(parts[1])
        else:
            print_help()
    elif cmd == "start":
        if len(parts) > 1:
            start_listening(parts[1])
        else:
            print("Usage: start <filename>")
    elif cmd == "stop":
        stop_listening()
    elif cmd == "display":
        display_log()
    elif cmd == "send":
        if len(parts) > 1:
            send_data(" ".join(parts[1:]))
        else:
            print("Usage: send <data>")
    elif cmd == "write":
        if len(parts) > 1:
            write_to_log(" ".join(parts[1:]))
        else:
            print("Usage: write <data>")
    elif cmd == "exit":
        global running
        running = False
        print("Exiting...")
        sys.exit(0)
    else:
        print(f"Unknown command: {cmd}. Try 'help'.")


def main():
    """Main function to run the data logger."""
    initialize_gpio()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    global running

    while running:
        try:
            command = input("Data Logger > ").strip()
            process_command(command)
        except Exception as e:
            print(f"An error occurred: {e}")

    # Ensure cleanup even if the loop exits normally (e.g., after an error)
    if receive_thread and receive_thread.is_alive():
        stop_listening()
    GPIO.cleanup()
    print("Cleanup complete.")


if __name__ == "__main__":
    main()

