        for cmd, msg in help_messages.items():
            print(f"{cmd}: {msg}")


def process_command(command):
    """Processes user commands."""
    parts = command.split()
    if not parts:
        return

    cmd = parts[0].lower()

    if cmd == "help":
        if len(parts) > 1:
            print_help(parts[1])
        else:
            print_help()
    elif cmd == "start":
        if len(parts) > 1:
            start_listening(parts[1])
        else:
            print("Usage: start <filename>")
    elif cmd == "stop":
        stop_listening()
    elif cmd == "display":
        display_log()
    elif cmd == "send":
        if len(parts) > 1:
            send_data(" ".join(parts[1:]))
        else:
            print("Usage: send <data>")
    elif cmd == "write":
        if len(parts) > 1:
            write_to_log(" ".join(parts[1:]))
        else:
            print("Usage: write <data>")
    elif cmd == "exit":
        global running
        running = False
        print("Exiting...")
        sys.exit(0)
    else:
        print(f"Unknown command: {cmd}. Try 'help'.")


def main():
    """Main function to run the data logger."""
    initialize_gpio()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    global running

    while running:
        try:
            command = input("Data Logger > ").strip()
            process_command(command)
        except Exception as e:
            print(f"An error occurred: {e}")

    # Ensure cleanup even if the loop exits normally (e.g., after an error)
    if receive_thread and receive_thread.is_alive():
        stop_listening()
    GPIO.cleanup()
    print("Cleanup complete.")


if __name__ == "__main__":
    main()

