import time
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# Configuration constants
LED_GPIO_PIN = 18
PWM_FREQUENCY = 1000
I2C_SCL_PIN = board.SCL
I2C_SDA_PIN = board.SDA

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(I2C_SCL_PIN, I2C_SDA_PIN)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_light_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor."""
    try:
        return adafruit_tsl2561.TSL2561(i2c_bus)
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}")
        return None

def initialize_gpio(led_pin, pwm_frequency):
    """Initialize GPIO for LED control with PWM."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(led_pin, GPIO.OUT)
    pwm_led = GPIO.PWM(led_pin, pwm_frequency)
    pwm_led.start(0)
    return pwm_led

def read_light_level(sensor):
    """Read the ambient light level from the sensor."""
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None

def set_led_brightness(pwm_led, brightness_level):
    """Set the LED brightness using PWM duty cycle."""
    try:
        pwm_led.ChangeDutyCycle(brightness_level)
    except Exception as e:
        print(f"Error setting LED brightness: {e}")

def main():
    """Main function to control LED brightness based on ambient light."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        i2c_bus.deinit()
        return

    pwm_led = initialize_gpio(LED_GPIO_PIN, PWM_FREQUENCY)

    try:
        while True:
            light_level = read_light_level(light_sensor)
            if light_level is not None:
                # Scale light level to a 0-100 duty cycle
                brightness = min(max(int(light_level / 10), 0), 100)
                set_led_brightness(pwm_led, brightness)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        pwm_led.stop()
        GPIO.cleanup()
        i2c_bus.deinit()
        print("GPIO and I2C cleaned up.")

if __name__ == "__main__":
    main()

