import RPi.GPIO as GPIO
import time
import logging
import functools

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pin numbers using BCM numbering
CLK_PIN = 17
DT_PIN = 18

# Debounce time in seconds
DEBOUNCE_TIME = 0.005

def setup_gpio(clk_pin, dt_pin):
    """Sets up the GPIO pins for the rotary encoder."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(clk_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(dt_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        logging.info("GPIO setup successful.")
        return True
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        return False

def validate_callback(callback):
    """Validates that the provided callback is callable."""
    if not callable(callback):
        raise ValueError("Callback must be a callable function.")

def create_encoder(clk_pin, dt_pin, callback=None, initial_value=0):
    """Creates a rotary encoder object."""

    if not setup_gpio(clk_pin, dt_pin):
        raise RuntimeError("GPIO setup failed; encoder creation aborted.")

    validate_callback(callback)

    last_state = GPIO.input(clk_pin)
    value = initial_value

    def _callback(channel):
        """Internal callback function to handle rotary encoder events."""
        nonlocal last_state, value  # Access and modify outer scope variables

        try:
            current_state = GPIO.input(clk_pin)
            if current_state != last_state:
                if GPIO.input(dt_pin) != current_state:
                    value += 1
                else:
                    value -= 1
                last_state = current_state
                if callback:
                    callback(value)
        except Exception as e:
            logging.error(f"Error in internal callback: {e}")

    # Set up interrupt handlers with debounce
    GPIO.add_event_detect(clk_pin, GPIO.BOTH, callback=_callback, bouncetime=int(DEBOUNCE_TIME * 1000))
    GPIO.add_event_detect(dt_pin, GPIO.BOTH, callback=_callback, bouncetime=int(DEBOUNCE_TIME * 1000)) # Added DT pin detection

    return {
        'value': value,
        'get_value': lambda: value,  # Return a lambda function for current value
        'cleanup': lambda: None # Placeholder for cleanup, will be implemented later
    }



def main():
    """Main function to demonstrate the rotary encoder usage."""

    def rotation_callback(value):
        """Callback function to handle rotation events."""
        logging.info(f"Rotary encoder value: {value}")

    try:
        encoder = create_encoder(CLK_PIN, DT_PIN, callback=rotation_callback, initial_value=50)
        logging.info(f"Initial encoder value: {encoder['get_value']()}")

        # Keep the program running to listen for events
        while True:
            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if 'encoder' in locals(): # Check if encoder was created before cleanup
            encoder['cleanup']()


if __name__ == "__main__":
    main()

