# Configuration constants
LED_GPIO_PIN = 18
PWM_FREQUENCY = 1000  # Hz
SLEEP_INTERVAL = 1  # seconds

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_light_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor."""
    try:
        return adafruit_tsl2561.TSL2561(i2c_bus)
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}")
        return None

def initialize_gpio(led_pin, pwm_frequency):
    """Initialize GPIO for LED control with PWM."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(led_pin, GPIO.OUT)
    pwm = GPIO.PWM(led_pin, pwm_frequency)
    pwm.start(0)  # Start with 0% duty cycle
    return pwm

def read_light_level(sensor):
    """Read ambient light level from the sensor."""
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None

def set_led_brightness(pwm, brightness_percent):
    """Set the LED brightness using PWM duty cycle."""
    try:
        pwm.ChangeDutyCycle(brightness_percent)
    except Exception as e:
        print(f"Error setting LED brightness: {e}")

def main():
    """Main function to read light and control LED brightness."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        return

    led_pwm = initialize_gpio(LED_GPIO_PIN, PWM_FREQUENCY)

    try:
        while True:
            light_level = read_light_level(light_sensor)
            if light_level is not None:
                print(f"Ambient Light: {light_level:.2f} lux")
                brightness = min(max(light_level / 100, 0), 100)  # Scale to 0-100%
                set_led_brightness(led_pwm, brightness)
                print(f"LED Brightness: {brightness:.2f}%")
            time.sleep(SLEEP_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        led_pwm.stop()
        GPIO.cleanup()
        if i2c_bus:
            i2c_bus.deinit()

if __name__ == "__main__":
    main()

