import time
import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO

# Define GPIO pin for the water pump relay
PUMP_PIN = 17

# Define soil moisture threshold
MOISTURE_THRESHOLD = 500

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_soil_sensor(i2c_bus):
    """Initialize the soil moisture sensor."""
    try:
        sensor = adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=0x36)
        return sensor
    except Exception as e:
        print(f"Error initializing soil moisture sensor: {e}")
        return None

def initialize_gpio():
    """Initialize the GPIO pin for the water pump."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PUMP_PIN, GPIO.OUT)
        GPIO.output(PUMP_PIN, GPIO.LOW)  # Ensure pump is initially off
    except Exception as e:
        print(f"Error initializing GPIO: {e}")

def read_soil_moisture(sensor):
    """Read the soil moisture level from the sensor."""
    try:
        moisture = sensor.moisture_read()
        return moisture
    except Exception as e:
        print(f"Error reading soil moisture: {e}")
        return None

def control_water_pump(moisture_level):
    """Control the water pump based on the soil moisture level."""
    try:
        if moisture_level is not None:
            if moisture_level < MOISTURE_THRESHOLD:
                GPIO.output(PUMP_PIN, GPIO.HIGH)  # Turn on pump
                pump_status = "ON"
            else:
                GPIO.output(PUMP_PIN, GPIO.LOW)  # Turn off pump
                pump_status = "OFF"
            return pump_status
        else:
            return "UNKNOWN"
    except Exception as e:
        print(f"Error controlling water pump: {e}")
        return "ERROR"

def main():
    """Main function to read soil moisture and control the water pump."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    soil_sensor = initialize_soil_sensor(i2c_bus)
    if soil_sensor is None:
        return

    initialize_gpio()

    try:
        while True:
            moisture = read_soil_moisture(soil_sensor)
            pump_status = control_water_pump(moisture)

            print(f"Soil Moisture: {moisture}, Pump Status: {pump_status}")

            time.sleep(10)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        # Ensure pump is off and clean up GPIO on exit
        GPIO.output(PUMP_PIN, GPIO.LOW)
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting...")

if __name__ == "__main__":
    main()

