import time
import smbus2
import adafruit_ccs811

# I2C bus and CCS811 address for the air quality sensor
I2C_BUS_NUMBER = 1
CCS811_I2C_ADDRESS = 0x5A

def initialize_sensor(i2c_bus):
    """Initialize the CCS811 sensor and return the sensor object."""
    try:
        sensor = adafruit_ccs811.CCS811(i2c_bus, address=CCS811_I2C_ADDRESS)
        # Check if the sensor is detected
        if sensor.get_status() == adafruit_ccs811.CCS811_STATUS_READY:
            return sensor
        else:
            raise RuntimeError("CCS811 sensor not detected or not ready.")
    except OSError as e:
        raise OSError(f"Error initializing CCS811: {e}")

def read_co2_concentration(sensor):
    """Read and return the CO2 concentration from the sensor in ppm."""
    try:
        if sensor.data_ready:
            return sensor.eco2
        else:
            return None
    except OSError as e:
        raise OSError(f"Error reading CO2 concentration: {e}")

def main():
    """Main function to read and display CO2 levels."""
    try:
        # Initialize the I2C bus
        i2c_bus = smbus2.SMBus(I2C_BUS_NUMBER)
        # Initialize the CCS811 sensor
        sensor = initialize_sensor(i2c_bus)

        # Read CO2 concentration multiple times
        for _ in range(5):
            try:
                co2_ppm = read_co2_concentration(sensor)
                if co2_ppm is not None:
                    print(f"CO2 Concentration: {co2_ppm} ppm")
                else:
                    print("CO2 data not ready yet.")
            except OSError as e:
                print(f"Error reading CO2: {e}")
            time.sleep(2)

    except OSError as e:
        print(f"Error: {e}")
    except RuntimeError as e:
        print(f"Runtime Error: {e}")
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        # No specific cleanup needed for smbus2, but good practice to include
        print("Exiting program.")

if __name__ == "__main__":
    main()

