import smbus2
import time
import logging
import signal
import sys
from datetime import datetime

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants for DS1338 I2C address and register map
DS1338_I2C_ADDRESS = 0x68
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07

# Global variable to track program running state for graceful shutdown
running = True

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global running
    logging.info("Received signal, shutting down...")
    running = False

def bcd_to_int(bcd_value):
    """Converts a BCD value to an integer."""
    try:
        return (bcd_value >> 4) * 10 + (bcd_value & 0x0F)
    except TypeError:
        logging.error("Invalid BCD value provided.")
        return None

def int_to_bcd(int_value):
    """Converts an integer to BCD format."""
    if not 0 <= int_value <= 99:
        logging.error("Integer value must be between 0 and 99 for BCD conversion.")
        return None
    return (int_value // 10 << 4) | (int_value % 10)

def read_register(bus, register_address):
    """Reads a byte from the specified register."""
    try:
        return bus.read_byte_data(DS1338_I2C_ADDRESS, register_address)
    except IOError as e:
        logging.error(f"I2C read error: {e}")
        return None

def write_register(bus, register_address, value):
    """Writes a byte to the specified register."""
    try:
        bus.write_byte_data(DS1338_I2C_ADDRESS, register_address, value)
    except IOError as e:
        logging.error(f"I2C write error: {e}")

def read_datetime(bus, century=21):
    """Reads the date and time from the RTC and returns a datetime object."""
    try:
        year = bcd_to_int(read_register(bus, REG_YEAR))
        month = bcd_to_int(read_register(bus, REG_MONTH))
        date = bcd_to_int(read_register(bus, REG_DATE))
        day = bcd_to_int(read_register(bus, REG_DAY))
        hours = bcd_to_int(read_register(bus, REG_HOURS) & 0x3F)  # Mask 24/12 hour bit and convert to int
        minutes = bcd_to_int(read_register(bus, REG_MINUTES))
        seconds = bcd_to_int(read_register(bus, REG_SECONDS))

        if None in (year, month, date, day, hours, minutes, seconds):
            raise ValueError("Error reading RTC data.")

        year = (century - 1) * 100 + year  # Apply century
        return datetime(year, month, date, hours, minutes, seconds)
    except ValueError as e:
        logging.error(f"Error constructing datetime object: {e}")
        return None
    except Exception as e:
        logging.error(f"Unexpected error in read_datetime: {e}")
        return None

def write_all(bus, seconds=None, minutes=None, hours=None, day=None, date=None, month=None, year=None):
    """Writes date and time to the RTC registers."""
    try:
        if seconds is not None:
            write_register(bus, REG_SECONDS, int_to_bcd(seconds))
        if minutes is not None:
            write_register(bus, REG_MINUTES, int_to_bcd(minutes))
        if hours is not None:
            write_register(bus, REG_HOURS, int_to_bcd(hours))  # Ensure 24-hour format
        if day is not None:
            write_register(bus, REG_DAY, int_to_bcd(day))
        if date is not None:
            write_register(bus, REG_DATE, int_to_bcd(date))
        if month is not None:
            write_register(bus, REG_MONTH, int_to_bcd(month))
        if year is not None:
            write_register(bus, REG_YEAR, int_to_bcd(year % 100)) # Store only last two digits
        logging.info("RTC time updated successfully.")
    except TypeError as e:
        logging.error(f"Invalid time value provided: {e}")
    except Exception as e:
        logging.error(f"Error writing to RTC: {e}")

def main():
    """Main function to demonstrate RTC interaction."""
    global running
    try:
        bus = smbus2.SMBus(1)  # Initialize I2C bus
        # Verify DS1338 presence by reading its address
        device_address = read_register(bus, REG_SECONDS)
        if device_address is None:
            raise IOError("DS1338 not found at I2C address 0x68. Check wiring and address.")

        logging.info("DS1338 RTC found and initialized.")

        while running:
            current_time = read_datetime(bus)
            if current_time:
                logging.info(f"Current RTC time: {current_time}")

            # Example: Update the time (uncomment to use)
            # write_all(bus, seconds=30, minutes=45, hours=14, date=25, month=4, year=24)

            time.sleep(5)

    except IOError as e:
        logging.error(f"I2C communication error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Exiting program.")
        if 'bus' in locals():
            bus.close()  # Ensure I2C bus is closed
        sys.exit(0)

if __name__ == "__main__":
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    main()

