import serial
import time

# GPS settings for Raspberry Pi Zero W
SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
TIMEOUT = 1

def open_gps_port(port, baud, timeout):
    """Opens the GPS serial port."""
    try:
        return serial.Serial(port, baud, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_gps_data(serial_port):
    """Reads a line of data from the serial port."""
    try:
        return serial_port.readline().decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def parse_gprmc_data(data):
    """Parses GPRMC data to extract latitude and longitude."""
    if not data.startswith("$GPRMC"):
        return None, None

    parts = data.split(",")
    if len(parts) < 10:
        print("Incomplete GPRMC data")
        return None, None

    if parts[2] != 'A':
        print("Invalid GPS data (status not A)")
        return None, None

    latitude = decode_coordinate(parts[3])
    longitude = decode_coordinate(parts[5])
    return latitude, longitude

def decode_coordinate(coordinate):
    """Converts GPS coordinate format DDDMM.MMMMM to DD deg MM.MMMMM min."""
    try:
        parts = coordinate.split('.')
        degrees = int(parts[0][:-2])
        minutes = float(parts[0][-2:])
        decimal = float(parts[1])
        return degrees + (minutes + decimal / 60.0)
    except (ValueError, IndexError) as e:
        print(f"Error decoding coordinate: {e}")
        return None

def main():
    """Main function to read and parse GPS data."""
    serial_connection = open_gps_port(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to open GPS port. Exiting.")
        return

    try:
        while True:
            gps_data = read_gps_data(serial_connection)
            if gps_data:
                latitude, longitude = parse_gprmc_data(gps_data)
                if latitude is not None and longitude is not None:
                    print(f"Latitude: {latitude}, Longitude: {longitude}")
            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")

    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("GPS port closed.")

if __name__ == "__main__":
    main()

