import json
import time
import logging
from threading import Lock
from http.server import BaseHTTPRequestHandler, HTTPServer
import serial
import RPi.GPIO as GPIO
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_SERIAL_PORT = '/dev/ttyUSB0'
DEFAULT_BAUDRATE = 9600
DEFAULT_TIMEOUT = 1  # seconds
DATA_STORE_FILE = 'data.json'

# Global variables
data_store = []
data_lock = Lock()
serial_port = None  # Serial port object
server = None  # HTTP server object

# Custom exception classes
class SerialCommunicationError(Exception):
    pass

class DataValidationError(Exception):
    pass

class HTTPError(Exception):
    pass

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    logging.info('Shutting down gracefully...')
    if serial_port:
        try:
            serial_port.close()
            logging.info('Serial port closed.')
        except Exception as e:
            logging.error(f'Error closing serial port: {e}')
    if server:
        server.shutdown()
    sys.exit(0)

# Register signal handler
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Function to initialize the serial port
def initialize_serial(port, baudrate, timeout):
    global serial_port
    try:
        serial_port = serial.Serial(port, baudrate, timeout=timeout)
        logging.info(f'Serial port {port} initialized.')
        return serial_port
    except serial.SerialException as e:
        logging.error(f'Error opening serial port {port}: {e}')
        return None

# Function to read data from the serial port
def read_serial_data(serial_port, timeout):
    try:
        if serial_port is None:
            raise SerialCommunicationError("Serial port is not initialized.")
        serial_port.timeout = timeout  # Set timeout for reading
        response = serial_port.readline().decode('ascii', errors='replace').strip()
        return response
    except serial.SerialException as e:
        raise SerialCommunicationError(f'Error reading from serial port: {e}')
    except Exception as e:
        raise SerialCommunicationError(f'Unexpected error during serial read: {e}')

# Function to write data to the serial port
def write_serial_data(serial_port, command):
    try:
        if serial_port is None:
            raise SerialCommunicationError("Serial port is not initialized.")
        serial_port.write(command.encode('ascii'))
        logging.debug(f'Wrote to serial: {command}')
    except serial.SerialException as e:
        raise SerialCommunicationError(f'Error writing to serial port: {e}')
    except Exception as e:
        raise SerialCommunicationError(f'Unexpected error during serial write: {e}')

# Function to load data from a JSON file
def load_data_from_file(filepath):
    global data_store
    try:
        with open(filepath, 'r') as f:
            data_store = json.load(f)
        logging.info(f'Data loaded from {filepath}')
    except FileNotFoundError:
        logging.warning(f'File not found: {filepath}')
    except json.JSONDecodeError as e:
        logging.error(f'Error decoding JSON from {filepath}: {e}')
    except Exception as e:
        logging.error(f'Error loading data from {filepath}: {e}')

# Function to save data to a JSON file
def save_data_to_file(filepath):
    try:
        with open(filepath, 'w') as f:
            json.dump(data_store, f, indent=4)
        logging.info(f'Data saved to {filepath}')
    except Exception as e:
        logging.error(f'Error saving data to {filepath}: {e}')

# Function to validate data
def validate_data(item):
    if not isinstance(item, dict):
        raise DataValidationError("Data must be a dictionary.")
    if 'id' not in item or not isinstance(item['id'], int):
        raise DataValidationError("ID must be an integer.")
    if 'name' not in item or not isinstance(item['name'], str) or not item['name']:
        raise DataValidationError("Name must be a non-empty string.")
    if 'done' not in item or not isinstance(item['done'], bool):
        raise DataValidationError("Done must be a boolean.")

# Function to create a new item
def create_item(name, done):
    new_id = data_store[-1]['id'] + 1 if data_store else 1
    new_item = {'id': new_id, 'name': name, 'done': done}
    return new_item

# Function to update an item
def update_item(item_id, name, done):
    for item in data_store:
        if item['id'] == item_id:
            item['name'] = name
            item['done'] = done
            return
    raise DataValidationError(f"Item with ID {item_id} not found.")

# Function to delete an item
def delete_item(item_id):
    global data_store
    data_store = [item for item in data_store if item['id'] != item_id]

# HTTP request handler
class DataRequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        try:
            if self.path == '/version':
                self.handle_version()
            elif self.path == '/data':
                self.handle_data_get()
            else:
                self.handle_not_found()
        except HTTPError as e:
            self.send_response(e.code)
            self.send_header('Content-type', 'application/json')
            self.end_headers()
            self.wfile.write(e.message.encode('utf-8'))
        except Exception as e:
            logging.error(f'Error handling GET request: {e}')
            self.send_response(500)
            self.send_header('Content-type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps({'error': str(e)}).encode('utf-8'))

    def do_POST(self):
        try:
            if self.path == '/data':
                self.handle_data_post()
            else:
                self.handle_not_found()
        except HTTPError as e:
            self.send_response(e.code)
            self.send_header('Content-type', 'application/json')
            self.end_headers()
            self.wfile.write(e.message.encode('utf-8'))
        except Exception as e:
            logging.error(f'Error handling POST request: {e}')
            self.send_response(500)
            self.send_header('Content-type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps({'error': str(e)}).encode('utf-8'))

    def handle_version(self):
        if serial_port:
            try:
                command = "*IDN?\n"
                write_serial_data(serial_port, command)
                response = read_serial_data(serial_port, timeout=DEFAULT_TIMEOUT)
                if response:
                    self.send_response(200)
                    self.send_header('Content-type', 'text/plain')
                    self.end_headers()
                    self.wfile.write(response.encode('utf-8'))
                else:
                    raise HTTPError(504, "No response received from serial device.")
            except SerialCommunicationError as e:
                raise HTTPError(500, str(e))
        else:
            raise HTTPError(500, "Serial port not initialized.")

    def handle_data_get(self):
        with data_lock:
            json_data = json.dumps(data_store)
        self.send_response(200)
        self.send_header('Content-type', 'application/json')
        self.end_headers()
        self.wfile.write(json_data.encode('utf-8'))

    def handle_data_post(self):
        content_length = int(self.headers['Content-Length'])
        post_data = self.rfile.read(content_length).decode('utf-8')
        try:
            data = json.loads(post_data)
            if 'name' not in data or 'done' not in data:
                raise DataValidationError("Name and done fields are required.")
            new_item = create_item(data['name'], data['done'])
            with data_lock:
                data_store.append(new_item)
            save_data_to_file(DATA_STORE_FILE)
            self.send_response(201)
            self.send_header('Content-type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps(new_item).encode('utf-8'))
        except json.JSONDecodeError:
            raise HTTPError(400, "Invalid JSON payload.")
        except DataValidationError as e:
            raise HTTPError(400, str(e))
        except Exception as e:
            logging.error(f'Error handling POST request: {e}')
            raise HTTPError(500, str(e))

    def handle_not_found(self):
        self.send_response(404)
        self.send_header('Content-type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({'error': 'Not found'}).encode('utf-8'))

    def handle_delete(self, item_id):
        try:
            with data_lock:
                delete_item(item_id)
            save_data_to_file(DATA_STORE_FILE)
            self.send_response(204)
            self.end_headers()
        except DataValidationError as e:
            raise HTTPError(400, str(e))
        except Exception as e:
            logging.error(f'Error handling DELETE request: {e}')
            raise HTTPError(500, str(e))

    def handle_put(self, item_id, data):
