    if not isinstance(item, dict):
        raise DataValidationError("Data must be a dictionary.")
    if 'id' not in item or not isinstance(item['id'], int):
        raise DataValidationError("ID must be an integer.")
    if 'name' not in item or not isinstance(item['name'], str) or not item['name']:
        raise DataValidationError("Name must be a non-empty string.")
    if 'done' not in item or not isinstance(item['done'], bool):
        raise DataValidationError("Done must be a boolean.")

