import serial
import time
import sys

# Configuration for the pulse oximeter serial port
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
DATA_BITS = serial.EIGHTBITS
PARITY = serial.PARITY_NONE
STOP_BITS = serial.STOPBITS_ONE
READ_INTERVAL_SECONDS = 1

def initialize_serial(port, baudrate, databits, parity, stopbits):
    """Initializes and returns a serial port object."""
    try:
        return serial.Serial(port, baudrate, databits, parity, stopbits, timeout=1)
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}")
        sys.exit(1)

def read_pulse_oximeter_data(serial_port):
    """Reads a line of data from the serial port and returns it."""
    try:
        return serial_port.readline().decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def process_pulse_oximeter_data(data_line):
    """Processes a line of comma-separated data to extract heart rate and SpO2."""
    if not data_line:
        return None, None

    try:
        heart_rate, spo2 = data_line.split(',')
        return int(heart_rate), int(spo2)
    except ValueError:
        print(f"Warning: Could not parse data line '{data_line}'. Skipping.")
        return None, None

def display_pulse_oximeter_data(heart_rate, spo2):
    """Prints the heart rate and SpO2 values to the console."""
    if heart_rate is not None and spo2 is not None:
        print(f'Heart Rate: {heart_rate} bpm, SpO2: {spo2} %')

def main():
    """Main function to read and display pulse oximeter data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, DATA_BITS, PARITY, STOP_BITS)

    try:
        while True:
            data = read_pulse_oximeter_data(serial_connection)
            if data:
                heart_rate, spo2 = process_pulse_oximeter_data(data)
                display_pulse_oximeter_data(heart_rate, spo2)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        if serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

