import serial
import time
import sys

# Define Bluetooth connection parameters
BLUETOOTH_PORT = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400
COMMAND_PREFIX = 'X'
TRANSMISSION_DELAY = 0.1

def create_bluetooth_connection(port, baudrate):
    """Establishes a connection to the Bluetooth device."""
    try:
        bluetooth = serial.Serial(port, baudrate)
        return bluetooth
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to connect to Bluetooth device: {e}")

def construct_command(command_string):
    """Prefixes the command with a specific character."""
    return COMMAND_PREFIX + command_string + '\n'

def transmit_command(bluetooth_connection, command_string):
    """Sends a command to the Bluetooth device."""
    try:
        bluetooth_connection.write(command_string.encode())
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to transmit command: {e}")

def main():
    """Main function to handle user input and send commands."""
    bluetooth_connection = None
    try:
        bluetooth_connection = create_bluetooth_connection(BLUETOOTH_PORT, BLUETOOTH_BAUD_RATE)

        while True:
            user_command = input("Enter command (or 'exit' to quit): ")
            if user_command.lower() == "exit":
                break
            command_to_send = construct_command(user_command)
            transmit_command(bluetooth_connection, command_to_send)
            time.sleep(TRANSMISSION_DELAY)

    except RuntimeError as e:
        print(f"Error: {e}")
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        if bluetooth_connection:
            bluetooth_connection.close()
            print("Bluetooth connection closed.")

if __name__ == "__main__":
    main()
    sys.exit(0)

